      /* (810) signal_set_tail ::= */ yytestcase(yyruleno==810);
      /* (812) transaction_end_tail ::= */ yytestcase(yyruleno==812);
      /* (910) resignal_tail ::= */ yytestcase(yyruleno==910);
      /* (920) statement_tail ::= */ yytestcase(yyruleno==920);
        break;
